  '  float cap = smoothstep(0.42, 0.95, yn);',
  '  float m = uMush * cap;',
  '  float ys = 1.0 - uMush * (0.62 * cap + 0.08);',
  '  float ang = atan(position.z, position.x);',
  '  float petal = 1.0 + m * (0.20 * sin(ang * 5.0 + 1.7) + 0.10 * sin(ang * 9.0 + 0.4));',
