const SHARD_N = 2600;
function needleGeometry() {
  const verts = [];
  const ring = [];
  const K = 5;
  for (let k = 0; k < K; k++) {
    const a = k / K * Math.PI * 2 + rr(-0.15, 0.15);
    const r = 0.5 * rr(0.6, 1.0);
    ring.push([Math.cos(a) * r, rr(-0.06, 0.06), Math.sin(a) * r]);
  }
  const top = [0, 0.5, 0], bot = [0, -0.5, 0];
  for (let k = 0; k < K; k++) {
    const a = ring[k], b = ring[(k + 1) % K];
    verts.push(top, a, b);
    verts.push(bot, b, a);
  }
  const pos = [];
  verts.forEach(v => pos.push(v[0], v[1], v[2]));
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.computeVertexNormals(); // non-indexed -> crisp flat facets
  return g;
}
const shardMat = new THREE.MeshStandardMaterial({
  color: 0xe8f1f8, metalness: 0.15, roughness: 0.08,
  envMapIntensity: 1.7, flatShading: true
});
