const shP0 = new Float32Array(SHARD_N * 3);
const shV0 = new Float32Array(SHARD_N * 3);
const shBirth = new Float32Array(SHARD_N);
const shLen = new Float32Array(SHARD_N);
const shWid = new Float32Array(SHARD_N);
const shAxis = new Float32Array(SHARD_N * 3);
const shOmega = new Float32Array(SHARD_N);
const shPhase = new Float32Array(SHARD_N);
{
  const col = new THREE.Color();
  const P = new THREE.Vector3();
  for (let i = 0; i < SHARD_N; i++) {
    let s;
    const u = rand();
    if (u < 0.55) s = 0.32 * Math.pow(rand(), 1.5);       // bulb-heavy
    else if (u < 0.94) s = rr(0.05, CUT_S);               // spine / tail
    else s = rr(CUT_S, 1.0);                              // severed tip region
    const isTip = s > CUT_S;
    const f = frameAt(s);
    const phi = rr(0, Math.PI * 2);
    const rad = radiusAt(s) * rr(0.0, 0.95);
    P.copy(spinePoint(s))
      .addScaledVector(f.N, Math.cos(phi) * rad)
      .addScaledVector(f.B, Math.sin(phi) * rad);
    shP0[i * 3] = P.x; shP0[i * 3 + 1] = P.y; shP0[i * 3 + 2] = P.z;

    let speed = rr(0.5, 1.7);
    if (s < 0.3) speed *= rr(1.3, 2.0); // catastrophic bulb burst
    if (isTip) speed *= 0.5;
    const axial = rr(-0.4, 0.4);
    shV0[i * 3] = f.N.x * Math.cos(phi) * speed + f.T.x * axial + rr(-0.15, 0.15);
    shV0[i * 3 + 1] = f.N.y * Math.cos(phi) * speed + f.T.y * axial + rr(-0.15, 0.15);
    shV0[i * 3 + 2] = f.N.z * Math.cos(phi) * speed + f.T.z * axial + rr(-0.15, 0.15);
    if (isTip) { shV0[i * 3] += 0.35; shV0[i * 3 + 1] += 0.6; shV0[i * 3 + 2] += 0.25; }

    shBirth[i] = isTip ? SNIP_T : waveTime(s);
    shLen[i] = s < 0.3 ? rr(0.07, 0.2) : rr(0.05, 0.16);
    shWid[i] = rr(0.008, 0.022);

    let ax = rr(-1, 1), ay = rr(-1, 1), az = rr(-1, 1);
    const al = 1 / Math.sqrt(ax * ax + ay * ay + az * az + 1e-6);
    shAxis[i * 3] = ax * al; shAxis[i * 3 + 1] = ay * al; shAxis[i * 3 + 2] = az * al;
    shOmega[i] = rr(2, 8) * (rand() < 0.5 ? -1 : 1);
    shPhase[i] = rr(0, Math.PI * 2);

    col.setHSL(0.55 + rand() * 0.08, 0.12 + rand() * 0.2, 0.78 + rand() * 0.18);
    shardMesh.setColorAt(i, col);
  }
  shardMesh.instanceColor.needsUpdate = true;
}

