// ---------------- analytic drag ballistics ----------------
// closed-form linear-drag trajectory: p = p0 + v0*A + g*(tau - A)/k,
// A = (1 - exp(-k*tau))/k  -> fully deterministic at any simTime.
const ZERO_M = new Float32Array(16); // all-zero scale matrix (hidden instance)
const _m = new THREE.Matrix4();
const _p = new THREE.Vector3();
const _q = new THREE.Quaternion();
const _s = new THREE.Vector3();
const _ax = new THREE.Vector3();
const _c = new THREE.Color();

function updateShards(t) {
  const arr = shardMesh.instanceMatrix.array;
  const K = 0.5, G = 0.8;
  for (let i = 0; i < SHARD_N; i++) {
    const tau = t - shBirth[i];
    if (tau <= 0) { arr.set(ZERO_M, i * 16); continue; }
    const e = Math.exp(-K * tau);
    const A = (1 - e) / K;
    const fall = G * (tau - A) / K;
    _p.set(
      shP0[i * 3] + shV0[i * 3] * A,
      shP0[i * 3 + 1] + shV0[i * 3 + 1] * A - fall,
      shP0[i * 3 + 2] + shV0[i * 3 + 2] * A
    );
    _ax.set(shAxis[i * 3], shAxis[i * 3 + 1], shAxis[i * 3 + 2]);
    _q.setFromAxisAngle(_ax, shOmega[i] * tau + shPhase[i]);
    const pop = smoothstep(0, 0.05, tau);
    _s.set(shWid[i] * pop, shLen[i] * pop, shWid[i] * pop);
    _m.compose(_p, _q, _s);
    _m.toArray(arr, i * 16);
  }
  shardMesh.instanceMatrix.needsUpdate = true;
}

function updateSpall(t) {
  const arr = spallMesh.instanceMatrix.array;
  const K = 0.4, G = 2.6;
  for (let i = 0; i < SPALL_N; i++) {
    const tau = t - spallBirth[i];
    if (tau <= 0) { arr.set(ZERO_M, i * 16); continue; }
    const e = Math.exp(-K * tau);
    const A = (1 - e) / K;
    const fall = G * (tau - A) / K;
    const sc = spallRad[i] * Math.min(1, tau / 0.05) * (1 - smoothstep(1.1, 1.7, tau));
    if (sc <= 0.0001) { arr.set(ZERO_M, i * 16); continue; }
    _p.set(
      spallP0[i * 3] + spallV0[i * 3] * A,
      spallP0[i * 3 + 1] + spallV0[i * 3 + 1] * A - fall,
      spallP0[i * 3 + 2] + spallV0[i * 3 + 2] * A
    );
    _q.set(0, 0, 0, 1);
    _s.set(sc, sc, sc);
    _m.compose(_p, _q, _s);
    _m.toArray(arr, i * 16);
  }
  spallMesh.instanceMatrix.needsUpdate = true;
}

function updateDust(t) {
  for (let i = 0; i < DUST_N; i++) {
    const tau = t - dBirth[i];
    if (tau <= 0) { dustAlpha[i] = 0; continue; }
    const k = dK[i];
    const e = Math.exp(-k * tau);
    const A = (1 - e) / k;
    const fall = dG[i] * (tau - A) / k;
    dustPos[i * 3] = dP0[i * 3] + dV0[i * 3] * A;
    dustPos[i * 3 + 1] = dP0[i * 3 + 1] + dV0[i * 3 + 1] * A - fall;
    dustPos[i * 3 + 2] = dP0[i * 3 + 2] + dV0[i * 3 + 2] * A;
    const fadeIn = smoothstep(0, 0.1, tau);
    const fadeOut = 1 - 0.75 * smoothstep(6.8, 8, t);
    dustAlpha[i] = dPeak[i] * fadeIn * fadeOut;
  }
  dustGeo.attributes.position.needsUpdate = true;
  dustGeo.attributes.aAlpha.needsUpdate = true;
}

// ---------------- pure deterministic renderAt(simTime) ----------------
function renderAt(t) {
  t = clamp(t, 0, DURATION);

  // --- glass: fracture clipping, stress fringes, elastic ringing ---
  const front = frontAt(t);
  const cut = t >= SNIP_T ? CUT_S : 1.0;
  const stress = stressAt(t);
  glassMat.uniforms.uTime.value = t;
  glassMat.uniforms.uFront.value = front;
  glassMat.uniforms.uCut.value = cut;
  glassMat.uniforms.uStress.value = stress;
  glassMesh.visible = Math.min(front, cut) > 0.002;

  tipMesh.visible = t >= SNIP_T;
  if (tipMesh.visible) {
    const tau = t - SNIP_T;
    tipMesh.position.set(
      cutPoint.x + 0.4 * tau + 0.1 * tau * tau,
      cutPoint.y + 0.7 * tau - 1.0 * tau * tau,
      cutPoint.z + 0.3 * tau
    );
    tipMesh.rotation.set(1.1 * tau, 0.4 * tau, -2.2 * tau);
    tipMat.uniforms.uTime.value = t;
    tipMat.uniforms.uStress.value = stress * 0.7;
  }

  // --- bullet: approach, mushrooming, recoil fall ---
  const mush = mushAt(t);
  bulletMat.uniforms.uMush.value = mush;
  const noseY = BULLET_LEN * (1 - mush * 0.70);
  let bx, by = IMPACT_Y, bz = 0, rz = Math.PI / 2, rx = 0;
  if (t <= IMPACT_T) {
    bx = CONTACT_X + BULLET_SPEED * (IMPACT_T - t) + noseY;
  } else {
    bx = CONTACT_X + noseY + 0.015 * mush;
    if (t > 2.35) {
      const tau = t - 2.35;
      bx += 0.55 * tau;
      by -= 1.3 * tau * tau;
      rz -= 1.4 * tau;
      rx = 0.5 * tau;
    }
  }
  bulletGroup.position.set(bx, by, bz);
  bulletGroup.rotation.set(rx, 0, rz);

  if (t < IMPACT_T) {
    streak.visible = true;
    streak.position.set(bx + 0.95, IMPACT_Y, 0);
    streakMat.opacity = 0.16 * smoothstep(0, 0.25, t) * (1 - smoothstep(1.05, 1.2, t));
  } else {
    streak.visible = false;
  }

  // --- clamp collar drops when the wave reaches the neck ---
  if (t >= COLLAR_BIRTH) {
    const tau = t - COLLAR_BIRTH;
    collar.position.set(neckPoint.x + 0.15 * tau, neckPoint.y - 1.1 * tau * tau, neckPoint.z + 0.1 * tau);
    collar.rotation.set(collarQ0.x + 1.6 * tau, collarQ0.y + 0.9 * tau, collarQ0.z);
    collar.quaternion.setFromEuler(new THREE.Euler(1.6 * tau, 0.9 * tau, 0.4 * tau));
  } else {
    collar.position.copy(neckPoint);
    collar.quaternion.copy(collarQ0);
  }

  // --- nippers: approach, close, snip, retract ---
  const ap = smoothstep(2.9, 3.45, t);
  const ret = smoothstep(4.15, 4.9, t);
  nipperRoot.position.set(
    lerp(nipRest.x, nipGrip.x, ap) + 0.55 * ret,
    lerp(nipRest.y, nipGrip.y, ap) + 0.7 * ret + 0.012 * Math.sin(t * 1.1) * (1 - ap),
    lerp(nipRest.z, nipGrip.z, ap) + 0.1 * ret
  );
  nipperRoot.rotation.z = -0.55;
  let th = 0.34;
  th -= (0.34 - 0.02) * smoothstep(3.45, SNIP_T - 0.02, t);
  th += 0.20 * smoothstep(4.1, 4.75, t);
  jawL.rotation.z = th;
  jawR.rotation.z = -th;
  handleL.rotation.z = 0.14 + th * 0.5;
  handleR.rotation.z = -(0.14 + th * 0.5);

  // --- particles ---
  updateShards(t);
  updateSpall(t);
  updateDust(t);

  // --- flashes & event lights ---
  const ie = impactEnv(t), ce = cutEnv(t), be = burstEnv(t);
  impactFlash.visible = ie > 0.002;
  impactFlash.material.opacity = ie * 0.85;
  const isc = 0.35 + 0.45 * ie;
  impactFlash.scale.set(isc, isc, 1);
  impactLight.intensity = 6 * ie;
  impactLight.position.set(CONTACT_X + 0.1, IMPACT_Y, 0.3);

  cutFlash.visible = ce > 0.002;
  cutFlash.material.opacity = ce * 0.95;
  const csc = 0.35 + 0.75 * ce;
  cutFlash.scale.set(csc, csc, 1);
  cutLight.intensity = 9 * ce;
  cutLight.position.copy(cutPoint);

  burstFlash.visible = be > 0.002;
  burstFlash.material.opacity = be * 0.9;
  const bsc = 0.6 + 2.4 * be;
  burstFlash.scale.set(bsc, bsc, 1);
  burstLight.intensity = 14 * be;
  burstLight.position.copy(bulbCenter);

  if (t >= WAVE_T0 && t <= WAVE_T1) {
    frontGlow.visible = true;
    const fp = spinePoint(front);
    frontGlow.position.copy(fp);
    frontGlow.material.opacity = 0.85 * smoothstep(WAVE_T0, WAVE_T0 + 0.08, t) * (1 - smoothstep(WAVE_T1 - 0.1, WAVE_T1, t));
    frontGlow.scale.set(0.4, 0.4, 1);
    frontLight.intensity = 3.5;
    frontLight.position.copy(fp);
  } else {
    frontGlow.visible = false;
    frontLight.intensity = 0;
  }

  renderer.render(scene, camera);
}

// ================================================================
//  Playback state machine: COUNTDOWN / PLAYING / PAUSED /
//  REFIRE_HOLD / ENDED  (wall-clock timers are speed-independent)
// ================================================================
const countdownEl = document.getElementById('countdown');
const scrubber = document.getElementById('scrubber');
const btnToggle = document.getElementById('btn-toggle');
const btnRefire = document.getElementById('btn-refire');
const iconPlay = document.getElementById('icon-play');
const iconPause = document.getElementById('icon-pause');
const pills = Array.prototype.slice.call(document.querySelectorAll('.speed-pill'));

let state = 'COUNTDOWN';
let simTime = 0;
let playbackSpeed = 1.0;
let countdownElapsed = 0;
let holdElapsed = 0;
let lastTs = null;

function setPlayingUI() {
  iconPause.style.display = '';
  iconPlay.style.display = 'none';
  btnToggle.setAttribute('aria-label', 'Pause');
}
function setPausedUI() {
  iconPause.style.display = 'none';
  iconPlay.style.display = '';
  btnToggle.setAttribute('aria-label', 'Play');
}
function hideCountdown() {
  countdownEl.style.display = 'none';
  countdownEl.textContent = '';
}
function showCountdownDigit() {
  countdownEl.style.display = 'block';
  countdownEl.textContent = countdownElapsed < 1 ? '3' : (countdownElapsed < 2 ? '2' : '1');
}
function enterPlaying() {
  state = 'PLAYING';
  setPlayingUI();
}
function endPlayback() {
  simTime = DURATION;
  scrubber.value = DURATION.toFixed(3);
  state = 'ENDED';
  setPausedUI();
}

btnToggle.addEventListener('click', function () {
  if (state === 'PLAYING') {
    state = 'PAUSED';
    setPausedUI();
  } else if (state === 'COUNTDOWN' || state === 'REFIRE_HOLD') {
    hideCountdown();
    simTime = 0;
    scrubber.value = '0';
    renderAt(0);
    state = 'PAUSED';
    setPausedUI();
  } else if (state === 'PAUSED') {
    enterPlaying();
  } else if (state === 'ENDED') {
    hideCountdown();
    simTime = 0;
    scrubber.value = '0';
    renderAt(0);
    enterPlaying();
  }
});

btnRefire.addEventListener('click', function () {
  hideCountdown();
  simTime = 0;
  scrubber.value = '0';
  renderAt(0);
  setPlayingUI();
  state = 'REFIRE_HOLD';
  holdElapsed = 0;
});

scrubber.addEventListener('input', function () {
  if (state === 'COUNTDOWN' || state === 'REFIRE_HOLD') hideCountdown();
  simTime = parseFloat(scrubber.value);
  renderAt(simTime);
  state = 'PAUSED';
  setPausedUI();
});

pills.forEach(function (pill) {
  pill.addEventListener('click', function () {
    playbackSpeed = parseFloat(pill.dataset.speed);
    pills.forEach(function (p) {
      const active = p === pill;
      p.classList.toggle('is-active', active);
      p.setAttribute('aria-checked', active ? 'true' : 'false');
    });
  });
});

// ---------------- main loop ----------------
function loop(ts) {
  requestAnimationFrame(loop);
  if (lastTs === null) {
    // first rAF callback after the initial resting scene has rendered
    lastTs = ts;
    countdownElapsed = 0;
    if (state === 'COUNTDOWN') showCountdownDigit();
    return;
  }
  const dt = Math.min((ts - lastTs) / 1000, 0.1);
  lastTs = ts;

  if (state === 'COUNTDOWN') {
    countdownElapsed += dt;
    if (countdownElapsed >= 3.0) {
      hideCountdown();
      enterPlaying();
      simTime = Math.min(DURATION, simTime + dt * playbackSpeed);
      scrubber.value = simTime.toFixed(3);
      renderAt(simTime);
      if (simTime >= DURATION) endPlayback();
    } else {
      showCountdownDigit();
      renderAt(0); // simTime stays exactly 0.000 during countdown
    }
  } else if (state === 'PLAYING') {
    simTime = Math.min(DURATION, simTime + dt * playbackSpeed);
    scrubber.value = simTime.toFixed(3);
    renderAt(simTime);
    if (simTime >= DURATION) endPlayback();
  } else if (state === 'REFIRE_HOLD') {
    holdElapsed += dt;
    if (holdElapsed >= 1.0) enterPlaying();
  }
  // PAUSED / ENDED: hold the current frame with no re-render
}

// ---------------- boot ----------------
renderAt(0);            // initial resting scene, simTime = 0.000
scrubber.value = '0';
requestAnimationFrame(loop);

})();
</script>
</body>
</html>
"}

