// Headless smoke test: stub THREE + DOM, execute the app, drive the state machine.
var rafCb = null;
var winListeners = {};

function magic() {
  var fn = function () {};
  return new Proxy(fn, {
    get: function (t, prop) {
      if (prop === Symbol.toPrimitive) return function () { return 0; };
      if (prop === 'then') return undefined;
      if (prop === Symbol.iterator) return undefined;
      return magic();
    },
    set: function () { return true; },
    apply: function () { return magic(); },
    construct: function () { return magic(); }
  });
}

function makeEl(id) {
  return {
    id: id, style: {}, textContent: '', value: '0', dataset: {},
    listeners: {},
    addEventListener: function (ev, fn) { (this.listeners[ev] = this.listeners[ev] || []).push(fn); },
    setAttribute: function () {}, getAttribute: function () { return null; },
    classList: { toggle: function () {}, add: function () {}, remove: function () {} }
  };
}

var els = {};
['stage', 'countdown', 'dock', 'btn-refire', 'btn-toggle', 'icon-play', 'icon-pause', 'speed-group', 'scrubber'].forEach(function (id) { els[id] = makeEl(id); });
var pills = ['0.25', '0.5', '1.0', '2.0'].map(function (s) { var e = makeEl('pill'); e.dataset.speed = s; return e; });

var ctx2d = {
  createRadialGradient: function () { return { addColorStop: function () {} }; },
  fillRect: function () {}, beginPath: function () {}, moveTo: function () {},
  lineTo: function () {}, stroke: function () {},
  fillStyle: '', strokeStyle: '', lineWidth: 0
};

var document = {
  getElementById: function (id) { return els[id] || makeEl(id); },
  querySelectorAll: function () { return pills; },
  createElement: function () { return { width: 0, height: 0, getContext: function () { return ctx2d; } }; }
};
var window = {
  innerWidth: 1920, innerHeight: 1080, devicePixelRatio: 2,
  addEventListener: function (ev, fn) { winListeners[ev] = fn; }
};
var THREE = magic();
function requestAnimationFrame(cb) { rafCb = cb; return 1; }

var app = Application.currentApplication();
app.includeStandardAdditions = true;
var code = app.read(Path('/private/tmp/pcd-sbx-qwen-4-max-opencode-bax0cp6a/tmp/opencode/inline.js'));

var log = [];
try {
  (0, eval)(code); // executes IIFE: builds scene, renderAt(0), registers rAF
  log.push('init+renderAt(0): OK');

  var ts = 0;
  function frames(n, step) { for (var i = 0; i < n; i++) { ts += step; rafCb(ts); } }

  // countdown: 30 frames x 0.1s wall = 3.0s -> PLAYING
  frames(1, 0); // first rAF: countdownElapsed = 0
  if (els['countdown'].textContent !== '3') throw new Error('countdown digit at 0: ' + els['countdown'].textContent);
  frames(10, 100);
  if (els['countdown'].textContent !== '2') throw new Error('countdown digit at 1s: ' + els['countdown'].textContent);
  frames(10, 100);
  if (els['countdown'].textContent !== '1') throw new Error('countdown digit at 2s: ' + els['countdown'].textContent);
  if (els['scrubber'].value !== '0') throw new Error('scrubber moved during countdown: ' + els['scrubber'].value);
  frames(11, 100); // crosses 3.0s -> PLAYING, simTime advances
  if (els['countdown'].style.display !== 'none') throw new Error('countdown not hidden after 3s');
  log.push('countdown 3-2-1 -> PLAYING: OK (scrubber=' + els['scrubber'].value + ')');

  frames(10, 100); // play ~1s of sim
  log.push('playing advance: OK (scrubber=' + els['scrubber'].value + ')');

  // toggle -> PAUSED -> PLAYING
  els['btn-toggle'].listeners.click[0]();
  if (els['btn-toggle'].getAttribute === null) {}
  els['btn-toggle'].listeners.click[0]();
  log.push('toggle pause/resume: OK');

  // scrub into heavy fracture phases (full shard/dust/spall evaluation)
  els['scrubber'].value = '5.000';
  els['scrubber'].listeners.input[0]();
  log.push('scrub renderAt(5.0): OK');
  els['scrubber'].value = '6.200';
  els['scrubber'].listeners.input[0]();
  log.push('scrub renderAt(6.2): OK');
  els['scrubber'].value = '8.000';
  els['scrubber'].listeners.input[0]();
  log.push('scrub renderAt(8.0): OK');
  els['scrubber'].value = '0.000';
  els['scrubber'].listeners.input[0]();
  log.push('scrub back to 0: OK');

  // speed pill
  pills[3].listeners.click[0]();
  log.push('speed pill 2.0x: OK');

  // re-fire from PAUSED -> REFIRE_HOLD (1s) -> PLAYING
  els['btn-refire'].listeners.click[0]();
  if (els['countdown'].style.display !== 'none') throw new Error('countdown visible during REFIRE_HOLD');
  if (els['scrubber'].value !== '0') throw new Error('refire did not reset scrubber');
  frames(11, 100);
  log.push('refire hold -> PLAYING: OK (scrubber=' + els['scrubber'].value + ')');

  // run to the end at 2x: scrub near end first to limit heavy frames
  els['scrubber'].value = '7.800';
  els['scrubber'].listeners.input[0]();
  els['btn-toggle'].listeners.click[0](); // resume
  frames(4, 100); // 0.4s wall * 2x = 0.8 sim -> reaches 8.0 -> ENDED
  if (els['scrubber'].value !== '8.000') throw new Error('did not clamp at DURATION: ' + els['scrubber'].value);
  log.push('ENDED clamp at 8.000: OK');

